message.content:
{
  "definition_simple": "罪や過ち、悪いことをしてしまうこと。",
  "definition_standard": "法律や規則、道徳などに背く行為をする。また、重大な過失や罪を犯す。",
  "pos": "v5s,vt",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "text": "彼は罪を犯した。"
    },
    {
      "tier": "T2",
      "text": "規則を犯してはいけない。"
    },
    {
      "tier": "T3",
      "text": "重大な過ちを犯してしまった。"
    },
    {
      "tier": "T4",
      "text": "法律を犯した者は罰せられる。"
    },
    {
      "tier": "T4",
      "text": "過失を犯さないように注意する。"
    },
    {
      "tier": "T5",
      "text": "禁忌を犯してその部屋に入った。"
    },
    {
      "tier": "T5",
      "text": "不可侵の領域を犯すような行為は許されない。"
    },
    {
      "tier": "T6",
      "text": "いかに巧妙に隠そうとも、悪事を犯せばいつかは露見する。"
    },
    {
      "tier": "T6",
      "text": "他人の権利を犯すことは法的に禁じられている。"
    },
    {
      "tier": "T6",
      "text": "倫理的な一線を犯した彼を誰も弁護しようとはしなかった。"
    }
  ],
  "morphological_forms": [
    {
      "label": "past_tense",
      "form": "犯した"
    },
    {
      "label": "te_form",
      "form": "犯して"
    }
  ],
  "morphology_wrong_forms": [
    {
      "form": "犯すた",
      "label": "past_tense",
      "explanation": "五段動詞の過去形は「いた」になるべきところを「た」に誤って直接接続しています。"
    },
    {
      "form": "犯してだ",
      "label": "past_tense",
      "explanation": "「犯して」はテ形であり、そのままでは過去形の文末述語として使えません。"
    },
    {
      "form": "犯しいて",
      "label": "te_form",
      "explanation": "五段動詞のイ音便規則を無視して余分な「い」を挿入した誤った形です。"
    }
  ],
  "primary_collocate": "罪",
  "collocation_distractors": [
    {
      "word": "宿題",
      "reason": "「宿題」は学校の課題であり、道徳や法律に背く「犯す」とは自然に共起しません。"
    },
    {
      "word": "散歩",
      "reason": "「散歩」は物理的な移動や気晴らしを意味する名詞であり、罪悪を伴う「犯す」の目的語になりません。"
    },
    {
      "word": "食事",
      "reason": "「食事」は日常的な栄養摂取の行為であり、違反行為を表す動詞「犯す」とは結びつきません。"
    }
  ],
  "collocation_wrong_collocate": "権利",
  "cloze_distractors": [
    {
      "word": "侵す",
      "reason": "「侵す」は領土やプライバシーなどを侵略・侵害する場合に使われ、法律や罪に対しては通常使いません。"
    },
    {
      "word": "冒す",
      "reason": "「冒す」は危険や困難を承知の上で進む場合に使われ、罪や規則を破る意味にはなりません。"
    },
    {
      "word": "果たす",
      "reason": "「果たす」は責任や義務、約束を達成・完了させる意味であり、悪い意味の行為には使いません。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は朝食を犯した。",
      "reason": "「朝食」は罪や規則ではないため、「犯す」の目的語として意味的に成立しません。"
    },
    {
      "sentence": "その山頂を犯すために登山した。",
      "reason": "山頂などの物理的な場所や領域に対しては「侵す」を使うのが適切であり、「犯す」は不自然です。"
    },
    {
      "sentence": "危険を犯して、彼は罪を犯した。",
      "reason": "前半の「危険を犯す」は「冒す」の誤用であり、文全体の文脈として不自然な重複が生じています。"
    }
  ],
  "spot_incorrect": {
    "sentence": "彼は重大な罪を侵して、警察に逮捕された。",
    "error_description": "法律や罪に背く場合は、領域の侵害を意味する「侵す」ではなく「犯す」を使うのが正しい漢字表記です。",
    "corrected": "彼は重大な罪を犯して、警察に逮捕された。"
  },
  "word_family_forms": [
    {
      "pos": "noun",
      "word": "犯人"
    },
    {
      "pos": "noun",
      "word": "犯罪"
    }
  ],
  "word_family_fake_forms": [
    "犯しき",
    "犯おし",
    "犯さり"
  ],
  "syn_ant_candidates": [
    {
      "type": "synonym",
      "word": "犯る"
    },
    {
      "type": "synonym",
      "word": "破る"
    },
    {
      "type": "antonym",
      "word": "守る"
    },
    {
      "type": "antonym",
      "word": "遵守する"
    }
  ],
  "particle_candidates": [
    {
      "particle": "を",
      "correct": true,
      "explanation": "「罪」は他動詞「犯す」の直接の目的語になるため、対格の「を」が正解です。"
    },
    {
      "particle": "に",
      "correct": false,
      "explanation": "「に」を使うと対象の場所や方向を示してしまい、目的語をとる他動詞の構造に合いません。"
    },
    {
      "particle": "で",
      "correct": false,
      "explanation": "「で」は手段や場所を表すため、違反する対象を表す名詞には接続できません。"
    },
    {
      "particle": "が",
      "correct": false,
      "explanation": "「が」は主格を示すため、「罪」が文の主語になってしまい意味が通じなくなります。"
    }
  ]
}
